// Valid: Length-prefixed UCSD/Pascal style parsing
fn parse_packet_data(bytes: &[u8]) -> Option<Vec<u8>> {
    if bytes.len() < 2 { return None; }
    let length = u16::from_be_bytes([bytes[0], bytes[1]]) as usize;
    if bytes.len() < 2 + length { return None; } // Strict validation
    Some(bytes[2..2 + length].to_vec())
